INSERT INTO rulings (id, date, text, uuid) VALUES (1, '2007-07-15', 'You draw the card when Bandage resolves, not when the damage is actually prevented.', '6d268c95-c176-5766-9a46-c14f739aba1c');
INSERT INTO rulings (id, date, text, uuid) VALUES (2, '2007-02-01', 'If you double a negative life total, you do the real math. A life total of -10 becomes -20.', '56f4935b-f6c5-59b9-88bf-9bcce20247ce');
INSERT INTO rulings (id, date, text, uuid) VALUES (3, '2007-07-15', 'Beacon of Immortality’s effect counts as life gain (or life loss, if the life total was negative) for effects that trigger on or replace life gain (or life loss).', '56f4935b-f6c5-59b9-88bf-9bcce20247ce');
INSERT INTO rulings (id, date, text, uuid) VALUES (4, '2007-07-15', 'If a Beacon is countered or doesn’t resolve, it’s put into its owner’s graveyard, not shuffled into the library.', '56f4935b-f6c5-59b9-88bf-9bcce20247ce');
INSERT INTO rulings (id, date, text, uuid) VALUES (5, '2010-08-15', 'The affected creature’s last known existence on the battlefield is checked to determine its toughness.', '7fef665c-36a1-5f7a-9299-cf8938708710');
INSERT INTO rulings (id, date, text, uuid) VALUES (6, '2008-08-01', 'The ability triggers even if the Specter’s damage is being redirected to an opponent. It does not trigger if damage that would have been dealt to the opponent is redirected to a nonopponent player or a creature, or if the damage is prevented.', '7fef665c-36a1-5f7a-9299-cf8938708710');
INSERT INTO rulings (id, date, text, uuid) VALUES (7, '2005-06-01', 'You choose how the damage will be divided among the target creatures at the time you cast Hail of Arrows. Each target must be dealt at least 1 damage. If any of those creatures becomes an illegal target before Hail of Arrows resolves, the division of dama', '7fef665c-36a1-5f7a-9299-cf8938708710');
INSERT INTO rulings (id, date, text, uuid) VALUES (8, '2007-07-15', 'High Ground’s effect is cumulative. If you have a creature that can already block an additional creature, now it can block three creatures.', '7fef665c-36a1-5f7a-9299-cf8938708710');
INSERT INTO rulings (id, date, text, uuid) VALUES (9, '2007-07-15', 'High Ground allows you to make some complicated blocks. For example, if you’re being attacked by three creatures (call them A, B, and C) and you control three creatures (X, Y, and Z), you can have X block A and B, Y block B and C, and Z block just C, amon', '7fef665c-36a1-5f7a-9299-cf8938708710');
INSERT INTO rulings (id, date, text, uuid) VALUES (10, '2009-10-01', 'A “blocking creature” is one that has been declared as a blocker this combat, or one that was put onto the battlefield blocking this combat. Unless that creature leaves combat, it continues to be a blocking creature through the end of combat step, even if', '7fef665c-36a1-5f7a-9299-cf8938708710');